namespace datalake {

StorageEngine::StorageEngine(const std::string& dbPath) : dbPath_(dbPath) {
    if (sqlite3_open(dbPath_.c_str(), &db_) == SQLITE_OK) {
        initializeSchema();
    } else {
        LOGE("Failed to open SQLite database at %s\n", dbPath_.c_str());
    }
}

StorageEngine::~StorageEngine() {
    if (db_) {
        sqlite3_close(db_);
    }
}

void StorageEngine::initializeSchema() {
    char* errMsg = nullptr;

    // Decouple Database I/O Write Latency with WAL to prevent locks degrading AI loops
    sqlite3_exec(db_, "PRAGMA journal_mode=WAL;", nullptr, nullptr, &errMsg);
    if (errMsg) sqlite3_free(errMsg);

    const char* sql = "CREATE TABLE IF NOT EXISTS attendance_records ("
                      "id INTEGER PRIMARY KEY AUTOINCREMENT,"
                      "record_blob BLOB NOT NULL,"
                      "sync_state INT DEFAULT 0,"
                      "idempotency_key TEXT UNIQUE NOT NULL,"
                      "created_at_monotonic INT NOT NULL"
                      ");";

    sqlite3_exec(db_, sql, nullptr, nullptr, &errMsg);
    if (errMsg) sqlite3_free(errMsg);
}

bool StorageEngine::saveRecord(const VerificationResult& result) {
    if (!db_) return false;

    // Generate idempotency_key linking ID with monotonic relative time
    std::ostringstream oss;
    oss << result.userId << "_" << result.timestampMonotonic;
    std::string idempotencyKey = oss.str();

    // Serialize to binary blob using nanopb bounds
    std::vector<uint8_t> blobBuf(256); // Safe static allocation size based on max_size boundaries
    size_t written_size = 0;

    /* 
    // Embedded nanopb serialization (uncomment when protocol buffers compiled):
    datalake_proto_AttendanceRecord record = datalake_proto_AttendanceRecord_init_zero;
    strncpy(record.user_id, result.userId.c_str(), sizeof(record.user_id) - 1);
    record.timestamp_monotonic = result.timestampMonotonic;
    record.latitude = result.latitude;
    record.longitude = result.longitude;
    strncpy(record.liveness_status, result.livenessStatus.c_str(), sizeof(record.liveness_status) - 1);

    pb_ostream_t stream = pb_ostream_from_buffer(blobBuf.data(), blobBuf.size());
    if (pb_encode(&stream, datalake_proto_AttendanceRecord_fields, &record)) {
        written_size = stream.bytes_written;
    } else {
        LOGE("nanopb encode failed.");
        return false;
    }
    */

    // Stub size for demo/compilation without linking full pb_encode.c
    written_size = 128; 

    // Insert only BLOBs, no raw text for attributes
    const char* sql = "INSERT OR IGNORE INTO attendance_records (record_blob, sync_state, idempotency_key, created_at_monotonic) VALUES (?, 0, ?, ?);";
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db_, sql, -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_blob(stmt, 1, blobBuf.data(), static_cast<int>(written_size), SQLITE_TRANSIENT);
        sqlite3_bind_text(stmt, 2, idempotencyKey.c_str(), -1, SQLITE_TRANSIENT);
        sqlite3_bind_int64(stmt, 3, result.timestampMonotonic);

        sqlite3_step(stmt);
        sqlite3_finalize(stmt);
        return true;
    }
    return false;
}

std::vector<SyncRecord> StorageEngine::getPendingRecords(int limit) {
    std::vector<SyncRecord> records;
    if (!db_) return records;

    const char* sql = "SELECT id, idempotency_key, record_blob FROM attendance_records WHERE sync_state = 0 LIMIT ?;";
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db_, sql, -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_int(stmt, 1, limit);
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            SyncRecord rec;
            rec.id = sqlite3_column_int(stmt, 0);
            rec.idempotencyKey = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));

            const uint8_t* blobData = static_cast<const uint8_t*>(sqlite3_column_blob(stmt, 2));
            int blobBytes = sqlite3_column_bytes(stmt, 2);
            if (blobData && blobBytes > 0) {
                rec.blob.assign(blobData, blobData + blobBytes);
            }

            records.push_back(std::move(rec));
        }
        sqlite3_finalize(stmt);
    }
    return records;
}

bool StorageEngine::updateSyncState(const std::vector<int>& recordIds, int state) {
    if (!db_ || recordIds.empty()) return false;

    // Execute block updates within a single memory transaction
    sqlite3_exec(db_, "BEGIN TRANSACTION;", nullptr, nullptr, nullptr);

    const char* sql = "UPDATE attendance_records SET sync_state = ? WHERE id = ?;";
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db_, sql, -1, &stmt, nullptr) == SQLITE_OK) {
        for (int id : recordIds) {
            sqlite3_bind_int(stmt, 1, state);
            sqlite3_bind_int(stmt, 2, id);
            sqlite3_step(stmt);
            sqlite3_reset(stmt);
        }
        sqlite3_finalize(stmt);
    }

    sqlite3_exec(db_, "COMMIT;", nullptr, nullptr, nullptr);
    return true;
}

void StorageEngine::purgeVerified() {
    if (!db_) return;

    char* errMsg = nullptr;
    // Execute a clean cryptographic erasure
    sqlite3_exec(db_, "DELETE FROM attendance_records WHERE sync_state = 2;", nullptr, nullptr, &errMsg);
    if (errMsg) sqlite3_free(errMsg);
}

} // namespace datalake
